INSERT INTO "FigApparatusRule" (
  "id","packageId","apparatus","levelCode","ruleType","ruleKey","valueJson","sourcePage","verificationStatus"
)
SELECT
  "floorRules"."id","floorRules"."packageId",'FLOOR_EXERCISE',"floorRules"."levelCode",
  'PRESCRIBED_ROUTINE','floor_routine',"floorRules"."valueJson","floorRules"."sourcePage",'VERIFIED'
FROM "floorRules"
WHERE EXISTS (SELECT 1 FROM "RulesetPackage" package WHERE package."id" = "floorRules"."packageId")
AND NOT EXISTS (
  SELECT 1 FROM "FigApparatusRule" existing
  WHERE existing."packageId" = "floorRules"."packageId"
    AND existing."apparatus" = 'FLOOR_EXERCISE'
    AND existing."levelCode" = "floorRules"."levelCode"
    AND existing."ruleKey" = 'floor_routine'
);
